  1495  /*
  3670   *
  3671   * Returns cram_container on success
  3672   *         NULL on failure or no container left (fd->err == 0).
  3673   */
  3674  cram_container *cram_read_container(cram_fd *fd) {
  3675      cram_container c2, *c;
  3676      int i, s;
  3677      size_t rd = 0;
  3678      uint32_t crc = 0;
  3679
  3680      fd->err = 0;
  3681      fd->eof = 0;
  3682
  3683      memset(&c2, 0, sizeof(c2));
  3684      if (CRAM_MAJOR_VERS(fd->version) == 1) {
  3685          if ((s = fd->vv.varint_decode32_crc(fd, &c2.length, &crc)) == -1) {
  3686              fd->eof = fd->empty_container ? 1 : 2;
  3687              return NULL;
  3688          } else {
  3689              rd+=s;
  3690          }
  3691      } else if (CRAM_MAJOR_VERS(fd->version) < 4) {
  3692          uint32_t len;
  3693          if ((s = int32_decode(fd, &c2.length)) == -1) {
  3694              if (CRAM_MAJOR_VERS(fd->version) == 2 &&
  3695                  CRAM_MINOR_VERS(fd->version) == 0)
  3696                  fd->eof = 1; // EOF blocks arrived in v2.1
  3697              else
  3698                  fd->eof = fd->empty_container ? 1 : 2;
  3699              return NULL;
  3700          } else {
  3701              rd+=s;
  3702          }
  3703          len = le_int4(c2.length);
  3704          crc = crc32(0L, (unsigned char *)&len, 4);
  3705      } else {
  3706          if ((s = fd->vv.varint_decode32_crc(fd, &c2.length, &crc))   == -1) {
  3707              fd->eof = fd->empty_container ? 1 : 2;
  3708              return NULL;
  3709          } else {
  3710              rd+=s;
  3711          }
  3712      }
  3713      if ((s = fd->vv.varint_decode32s_crc(fd, &c2.ref_seq_id, &crc))   == -1) return NULL; else rd+=s;
  3714      if (CRAM_MAJOR_VERS(fd->version) >= 4) {
  3715          int64_t i64;
  3716          if ((s = fd->vv.varint_decode64_crc(fd, &i64, &crc))== -1) return NULL; else rd+=s;
  3717          c2.ref_seq_start = i64;
  3718          if ((s = fd->vv.varint_decode64_crc(fd, &i64, &crc)) == -1) return NULL; else rd+=s;
  3719          c2.ref_seq_span = i64;
  3720      } else {
  3721          int32_t i32;
  3722          if ((s = fd->vv.varint_decode32_crc(fd, &i32, &crc))== -1) return NULL; else rd+=s;
  3723          c2.ref_seq_start = i32;
  3724          if ((s = fd->vv.varint_decode32_crc(fd, &i32, &crc)) == -1) return NULL; else rd+=s;
  3725          c2.ref_seq_span = i32;
  3726      }
  3727      if ((s = fd->vv.varint_decode32_crc(fd, &c2.num_records, &crc))  == -1) return NULL; else rd+=s;
  3728
  3729      if (CRAM_MAJOR_VERS(fd->version) == 1) {
  3730          c2.record_counter = 0;
  3731          c2.num_bases = 0;
  3732      } else {
  3733          if (CRAM_MAJOR_VERS(fd->version) >= 3) {
  3734              if ((s = fd->vv.varint_decode64_crc(fd, &c2.record_counter, &crc)) == -1)
  3735                  return NULL;
  3736              else
  3737                  rd += s;
  3738          } else {
  3739              int32_t i32;
  3740              if ((s = fd->vv.varint_decode32_crc(fd, &i32, &crc)) == -1)
  3741                  return NULL;
  3742              else
  3743                  rd += s;
  3744              c2.record_counter = i32;
  3745          }
