  4558  /*
  4559   * Writes a cram_file_def structure to cram_fd.
  4560   * Returns 0 on success
  4561   *        -1 on failure
  4562   */
  4563  int cram_write_file_def(cram_fd *fd, cram_file_def *def) {
  4564      return (hwrite(fd->fp, &def->magic[0], 26) == 26) ? 0 : -1;
  4565  }
